CREATE TABLE risk_settings(id TEXT PRIMARY KEY CHECK(id='global'),config_json TEXT NOT NULL CHECK(json_valid(config_json)),control_version INTEGER NOT NULL,updated_at_ms INTEGER NOT NULL,mutation_token TEXT NOT NULL) STRICT;
CREATE TABLE risk_api_keys(key_hash TEXT PRIMARY KEY,masked TEXT NOT NULL,nonce_b64 TEXT NOT NULL,ciphertext_b64 TEXT NOT NULL,created_at_ms INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'unknown',failure_count INTEGER NOT NULL DEFAULT 0,success_count INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',last_checked_at_ms INTEGER NOT NULL DEFAULT 0,frozen_until_ms INTEGER NOT NULL DEFAULT 0,last_latency_ms INTEGER NOT NULL DEFAULT 0,last_http_status INTEGER NOT NULL DEFAULT 0,last_tested INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL DEFAULT 0,total_latency_ms INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE risk_jobs(request_id TEXT PRIMARY KEY,context_json TEXT NOT NULL CHECK(json_valid(context_json)),payload_object_key TEXT,status TEXT NOT NULL CHECK(status IN('pending','processing','done','cancelled')),lease_owner TEXT,lease_expires_at_ms INTEGER NOT NULL DEFAULT 0,created_at_ms INTEGER NOT NULL,updated_at_ms INTEGER NOT NULL,result_json TEXT,config_version INTEGER NOT NULL,api_key_hash TEXT) STRICT;
CREATE INDEX risk_jobs_due ON risk_jobs(status,lease_expires_at_ms,created_at_ms);
CREATE TABLE risk_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,request_id TEXT NOT NULL UNIQUE,user_id TEXT,api_key_id TEXT,group_id TEXT,endpoint TEXT NOT NULL,provider TEXT NOT NULL,model TEXT NOT NULL,mode TEXT NOT NULL,action TEXT NOT NULL,flagged INTEGER NOT NULL,highest_category TEXT NOT NULL,highest_score REAL NOT NULL,matched_keyword TEXT NOT NULL DEFAULT '',category_scores_json TEXT NOT NULL,threshold_snapshot_json TEXT NOT NULL,input_excerpt TEXT NOT NULL,input_hash TEXT NOT NULL DEFAULT '',upstream_latency_ms INTEGER,error TEXT NOT NULL DEFAULT '',violation_count INTEGER NOT NULL DEFAULT 0,auto_banned INTEGER NOT NULL DEFAULT 0,email_sent INTEGER NOT NULL DEFAULT 0,effects_applied INTEGER NOT NULL DEFAULT 0,queue_delay_ms INTEGER,created_at_ms INTEGER NOT NULL) STRICT;
CREATE INDEX risk_logs_user ON risk_logs(user_id,flagged,created_at_ms);
CREATE INDEX risk_logs_created ON risk_logs(created_at_ms,id);
CREATE TABLE risk_hashes(input_hash TEXT PRIMARY KEY,created_at_ms INTEGER NOT NULL,expires_at_ms INTEGER NOT NULL) STRICT;
CREATE TABLE risk_bans(user_id TEXT PRIMARY KEY,log_id INTEGER NOT NULL,banned_state_version INTEGER NOT NULL,banned_control_version INTEGER NOT NULL,enabled_mutation_id TEXT NOT NULL,created_at_ms INTEGER NOT NULL,cleared_at_ms INTEGER) STRICT;
CREATE TABLE risk_ban_commands(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,log_id INTEGER NOT NULL,direction TEXT NOT NULL CHECK(direction IN('ban','unban')),expected_state_version INTEGER NOT NULL,expected_control_version INTEGER NOT NULL,expected_auth_version INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','applying','done','cancelled')),lease_owner TEXT,lease_expires_at_ms INTEGER NOT NULL DEFAULT 0,applied_state_version INTEGER,prepared INTEGER NOT NULL DEFAULT 0,prior_enabled_mutation_id TEXT,last_error TEXT NOT NULL DEFAULT '',created_at_ms INTEGER NOT NULL,updated_at_ms INTEGER NOT NULL) STRICT;
CREATE INDEX risk_ban_commands_due ON risk_ban_commands(status,lease_expires_at_ms,created_at_ms);
CREATE TABLE risk_outbox(id TEXT PRIMARY KEY,log_id INTEGER NOT NULL,user_id TEXT NOT NULL,event TEXT NOT NULL,due_at_ms INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,sent_at_ms INTEGER,last_error TEXT NOT NULL DEFAULT '',lease_owner TEXT,lease_expires_at_ms INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE risk_runtime(id TEXT PRIMARY KEY CHECK(id='global'),enqueued INTEGER NOT NULL DEFAULT 0,dropped INTEGER NOT NULL DEFAULT 0,processed INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,pre_block_checked INTEGER NOT NULL DEFAULT 0,pre_block_allowed INTEGER NOT NULL DEFAULT 0,pre_block_blocked INTEGER NOT NULL DEFAULT 0,pre_block_errors INTEGER NOT NULL DEFAULT 0,pre_block_latency_ms INTEGER NOT NULL DEFAULT 0,last_cleanup_at_ms INTEGER NOT NULL DEFAULT 0,last_cleanup_deleted_hit INTEGER NOT NULL DEFAULT 0,last_cleanup_deleted_non_hit INTEGER NOT NULL DEFAULT 0) STRICT;
INSERT INTO risk_runtime(id) VALUES('global');
ALTER TABLE gateway_risk_events ADD COLUMN projected_at_ms INTEGER;
INSERT INTO schema_migrations(version,name,applied_at_ms) VALUES(96,'risk_control',CAST(unixepoch('subsec')*1000 AS INTEGER));
